// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DoacaoRecorrente) predicate.DoacaoRecorrente {
	return predicate.DoacaoRecorrente(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DoacaoRecorrente) predicate.DoacaoRecorrente {
	return predicate.DoacaoRecorrente(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DoacaoRecorrente) predicate.DoacaoRecorrente {
	return predicate.DoacaoRecorrente(sql.NotPredicates(p))
}
